export function analysisSpecification(){return {schema:1,kind:'weekly_level_event_study',reference:{period:'previous_completed_calendar_week',field:'low',timezone:'Asia/Kolkata',week_start:'monday',missing_session:'unavailable',crossing_reset:'calendar_week'},event:{field:'close',op:'crosses_below',first_session:'observe_only'},outcomes:[5,10,20].map(horizon_sessions=>({field:'close',horizon_sessions})),output:'dated_observations'};}
