export function validStrategyConfig(c){return !!c.start&&!!c.end&&!!c.reserved_start&&c.start<=c.reserved_start&&c.reserved_start<=c.end&&Number.isFinite(c.capital)&&c.capital>=1&&c.capital<=1e10&&Number.isFinite(c.allocation_pct)&&c.allocation_pct>=.01&&c.allocation_pct<=100&&Number.isInteger(c.holding_sessions)&&c.holding_sessions>=1&&c.holding_sessions<=250&&Number.isFinite(c.fee_bps)&&c.fee_bps>=0&&c.fee_bps<=1000&&Number.isFinite(c.fixed_fee)&&c.fixed_fee>=0&&c.fixed_fee<=1e6&&Number.isFinite(c.slippage_bps)&&c.slippage_bps>=0&&c.slippage_bps<=1000;}
